   230	func (cs *checkoutService) PlaceOrder(ctx context.Context, req *pb.PlaceOrderRequest) (*pb.PlaceOrderResponse, error) {
   231		log.Infof("[PlaceOrder] user_id=%q user_currency=%q", req.UserId, req.UserCurrency)
   232	
   233		orderID, err := uuid.NewUUID()
   234		if err != nil {
   235			return nil, status.Errorf(codes.Internal, "failed to generate order uuid")
   236		}
   237	
   238		prep, err := cs.prepareOrderItemsAndShippingQuoteFromCart(ctx, req.UserId, req.UserCurrency, req.Address)
   239		if err != nil {
   240			return nil, status.Errorf(codes.Internal, err.Error())
   241		}
   242	
   243		total := pb.Money{CurrencyCode: req.UserCurrency,
   244			Units: 0,
   245			Nanos: 0}
   246		total = money.Must(money.Sum(total, *prep.shippingCostLocalized))
   247		for _, it := range prep.orderItems {
   248			multPrice := money.MultiplySlow(*it.Cost, uint32(it.GetItem().GetQuantity()))
   249			total = money.Must(money.Sum(total, multPrice))
   250		}
   251	
   252		txID, err := cs.chargeCard(ctx, &total, req.CreditCard)
   253		if err != nil {
   254			return nil, status.Errorf(codes.Internal, "failed to charge card: %+v", err)
   255		}
   256		log.Infof("payment went through (transaction_id: %s)", txID)
   257	
   258		shippingTrackingID, err := cs.shipOrder(ctx, req.Address, prep.cartItems)
   259		if err != nil {
   260			return nil, status.Errorf(codes.Unavailable, "shipping error: %+v", err)
   261		}
   262	
   263		_ = cs.emptyUserCart(ctx, req.UserId)
   264	
   265		orderResult := &pb.OrderResult{
