   269			ShippingAddress:    req.Address,
   270			Items:              prep.orderItems,
   271		}
   272	
   273		if err := cs.sendOrderConfirmation(ctx, req.Email, orderResult); err != nil {
   274			log.Warnf("failed to send order confirmation to %q: %+v", req.Email, err)
   275		} else {
   276			log.Infof("order confirmation email sent to %q", req.Email)
