117	function _carry (amount) {
118	  const fractionSize = Math.pow(10, 9);
119	  amount.nanos += (amount.units % 1) * fractionSize;
120	  amount.units = Math.floor(amount.units) + Math.floor(amount.nanos / fractionSize);
