 19	const logger = pino({
 20	  name: 'paymentservice-charge',
 21	  messageKey: 'message',
 22	  formatters: {
 23	    level (logLevelString, logLevelNum) {
 24	      return { severity: logLevelString }
 25	    }
 26	  }
