 30	class CreditCardError extends Error {
 31	  constructor (message) {
 32	    super(message);
 33	    this.code = 400; // Invalid argument error
 34	  }
 35	}
 36	
 37	class InvalidCreditCard extends CreditCardError {
 38	  constructor (cardType) {
 39	    super(`Credit card info is invalid`);
 40	  }
 41	}
 42	
 43	class UnacceptedCreditCard extends CreditCardError {
 44	  constructor (cardType) {
 45	    super(`Sorry, we cannot process ${cardType} credit cards. Only VISA or MasterCard is accepted.`);
 46	  }
 47	}
 48	
 49	class ExpiredCreditCard extends CreditCardError {
 50	  constructor (number, month, year) {
 51	    super(`Your credit card (ending ${number.substr(-4)}) expired on ${month}/${year}`);
 52	  }
 53	}
