 55	/**
 56	 * Verifies the credit card number and (pretend) charges the card.
 57	 *
 58	 * @param {*} request
 59	 * @return transaction_id - a random uuid.
 60	 */
 61	module.exports = function charge (request) {
 62	  const { amount, credit_card: creditCard } = request;
 63	  const cardNumber = creditCard.credit_card_number;
 64	  const cardInfo = cardValidator(cardNumber);
 65	  const {
 66	    card_type: cardType,
 67	    valid
 68	  } = cardInfo.getCardDetails();
 69	
 70	  if (!valid) { throw new InvalidCreditCard(); }
 71	
 72	  // Only VISA and mastercard is accepted, other card types (AMEX, dinersclub) will
 73	  // throw UnacceptedCreditCard error.
 74	  if (!(cardType === 'visa' || cardType === 'mastercard')) { throw new UnacceptedCreditCard(cardType); }
 75	
 76	  // Also validate expiration is > today.
 77	  const currentMonth = new Date().getMonth() + 1;
 78	  const currentYear = new Date().getFullYear();
 79	  const { credit_card_expiration_year: year, credit_card_expiration_month: month } = creditCard;
 80	  if ((currentYear * 12 + currentMonth) > (year * 12 + month)) { throw new ExpiredCreditCard(cardNumber.replace('-', ''), month, year); }
 81	
 82	  logger.info(`Transaction processed: ${cardType} ending ${cardNumber.substr(-4)} \
 83	    Amount: ${amount.currency_code}${amount.units}.${amount.nanos}`);
 84	
 85	  return { transaction_id: uuidv4() };
 86	};
