 23	class HipsterShopServer {
 24	  constructor(protoRoot, port = HipsterShopServer.PORT) {
 25	    this.port = port;
 26	
 27	    this.packages = {
 28	      hipsterShop: this.loadProto(path.join(protoRoot, 'demo.proto')),
 29	      health: this.loadProto(path.join(protoRoot, 'grpc/health/v1/health.proto'))
 30	    };
 31	
 32	    this.server = new grpc.Server();
 33	    this.loadAllProtos(protoRoot);
 34	  }
