 36	  /**
 37	   * Handler for PaymentService.Charge.
 38	   * @param {*} call  { ChargeRequest }
 39	   * @param {*} callback  fn(err, ChargeResponse)
 40	   */
 41	  static ChargeServiceHandler(call, callback) {
 42	    try {
 43	      logger.info(`PaymentService#Charge invoked with request ${JSON.stringify(call.request)}`);
 44	      const response = charge(call.request);
 45	      callback(null, response);
 46	    } catch (err) {
 47	      console.warn(err);
 48	      callback(err);
