 56	
 57	  listen() {
 58	    const server = this.server 
 59	    const port = this.port
 60	    server.bindAsync(
 61	      `[::]:${port}`,
 62	      grpc.ServerCredentials.createInsecure(),
 63	      function () {
 64	        logger.info(`PaymentService gRPC server started on port ${port}`);
 65	        server.start();
 66	      }
 67	    );
 68	  }
