 70	  loadProto(path) {
 71	    const packageDefinition = protoLoader.loadSync(
 72	      path,
 73	      {
 74	        keepCase: true,
 75	        longs: String,
 76	        enums: String,
 77	        defaults: true,
 78	        oneofs: true
 79	      }
 80	    );
 81	    return grpc.loadPackageDefinition(packageDefinition);
 82	  }
 83	
 84	  loadAllProtos(protoRoot) {
 85	    const hipsterShopPackage = this.packages.hipsterShop.hipstershop;
 86	    const healthPackage = this.packages.health.grpc.health.v1;
 87	
 88	    this.server.addService(
 89	      hipsterShopPackage.PaymentService.service,
 90	      {
