 24	    public class RedisCartStore : ICartStore
 25	    {
 26	        private readonly IDistributedCache _cache;
 27	
 28	        public RedisCartStore(IDistributedCache cache)
 29	        {
 30	            _cache = cache;
 31	        }
 32	
 33	        public async Task AddItemAsync(string userId, string productId, int quantity)
 34	        {
 35	            Console.WriteLine($"AddItemAsync called with userId={userId}, productId={productId}, quantity={quantity}");
 36	
 37	            try
 38	            {
 39	                Hipstershop.Cart cart;
 40	                var value = await _cache.GetAsync(userId);
 41	                if (value == null)
 42	                {
 43	                    cart = new Hipstershop.Cart();
 44	                    cart.UserId = userId;
 45	                    cart.Items.Add(new Hipstershop.CartItem { ProductId = productId, Quantity = quantity });
 46	                }
 47	                else
 48	                {
 49	                    cart = Hipstershop.Cart.Parser.ParseFrom(value);
 50	                    var existingItem = cart.Items.SingleOrDefault(i => i.ProductId == productId);
 51	                    if (existingItem == null)
 52	                    {
 53	                        cart.Items.Add(new Hipstershop.CartItem { ProductId = productId, Quantity = quantity });
 54	                    }
 55	                    else
 56	                    {
 57	                        existingItem.Quantity += quantity;
 58	                    }
 59	                }
 60	                await _cache.SetAsync(userId, cart.ToByteArray());
 61	            }
 62	            catch (Exception ex)
 63	            {
 64	                throw new RpcException(new Status(StatusCode.FailedPrecondition, $"Can't access cart storage. {ex}"));
 65	            }
 66	        }
 67	
 68	        public async Task EmptyCartAsync(string userId)
 69	        {
 70	            Console.WriteLine($"EmptyCartAsync called with userId={userId}");
 71	
 72	            try
 73	            {
 74	                var cart = new Hipstershop.Cart();
 75	                await _cache.SetAsync(userId, cart.ToByteArray());
 76	            }
 77	            catch (Exception ex)
 78	            {
 79	                throw new RpcException(new Status(StatusCode.FailedPrecondition, $"Can't access cart storage. {ex}"));
 80	            }
 81	        }
 82	
 83	        public async Task<Hipstershop.Cart> GetCartAsync(string userId)
 84	        {
 85	            Console.WriteLine($"GetCartAsync called with userId={userId}");
 86	
 87	            try
 88	            {
 89	                // Access the cart from the cache
 90	                var value = await _cache.GetAsync(userId);
 91	
 92	                if (value != null)
 93	                {
 94	                    return Hipstershop.Cart.Parser.ParseFrom(value);
 95	                }
 96	
 97	                // We decided to return empty cart in cases when user wasn't in the cache before
 98	                return new Hipstershop.Cart();
 99	            }
100	            catch (Exception ex)
101	            {
102	                throw new RpcException(new Status(StatusCode.FailedPrecondition, $"Can't access cart storage. {ex}"));
103	            }
104	        }
